1	import * as React from "react";
2	import { type LucideIcon } from "lucide-react";
3	
4	export type StatusTone = "neutral" | "success" | "warning" | "alert" | "info";
5	
6	const TONES: Record<StatusTone, string> = {
7	  neutral: "bg-surface-sunk text-ink-soft",
8	  success: "bg-success-tint text-success",
9	  warning: "bg-accent-tint text-accent-dark",
10	  alert: "bg-alert-tint text-alert",
11	  info: "bg-primary-tint text-primary-dark",
12	};
13	
14	/**
15	 * Generic status pill. Meaning is carried by the icon + text label together —
16	 * never by colour alone (the tone is reinforcement, not the signal).
17	 */
18	export function StatusBadge({
19	  tone = "neutral",
20	  icon: Icon,
21	  children,
22	}: {
23	  tone?: StatusTone;
24	  icon?: LucideIcon;
25	  children: React.ReactNode;
26	}) {
27	  return (
28	    <span
29	      className={[
30	        "inline-flex items-center gap-1.5 whitespace-nowrap rounded-pill px-2.5 py-1 text-sm font-bold",
31	        TONES[tone],
32	      ].join(" ")}
33	    >
34	      {Icon ? <Icon size={15} strokeWidth={2.25} aria-hidden="true" /> : null}
35	      {children}
36	    </span>
37	  );
38	}
